-- Lists, part 4 (L4 of the lists plan; Orel's defaults on issue #1): a
-- template's times open its lists by themselves, remind before they are due,
-- say when one is late, and close one nobody did as "לא נעשתה".
--
--   Shabbat     private.shabbat_times: candle lighting and havdalah for every
--               city of ISRAELI_CITIES (@domain/shabbat), every Friday from
--               November 2026 to the end of 2031, printed by
--               tooling/shabbat-table.test.ts, which also checks every row
--               against @domain/shabbat-times and says a year ahead when they
--               are about to run out. The database has no hebcal.
--               private.closes_on_shabbat is the rule /manage has (the
--               schedule on and closed on Shabbat, by default), and
--               private.shabbat_span the business's Shabbat that a Friday or a
--               Saturday belongs to, by its city (Tel Aviv while it has none).
--   stamps      list_schedules.opens_from, from when a time's openings count:
--               when it was saved, and again when its days or hours change,
--               it is switched back on or its template comes back
--               (save_list_template and restore_list_template of L1, each
--               with that one change), so a time saved after its own hour
--               starts with its next opening, never late today. The times L2
--               copied into every business count from this migration on.
--               lists.reopened_at (reopen_list of L1 sets it): a list opened
--               again by hand is never closed as missed.
--   openings    private.list_occurrences: when a time opens its lists and
--               when each is due, in the business's own zone and clock (a time
--               the spring change skips opens an hour later, one the autumn
--               change repeats is the later one, as Postgres reads them), or
--               around a published shift of its pattern. Nothing opens before
--               the time's opens_from or on a day before it starts, and a time
--               that follows a shift the settings no longer have opens nothing.
--               For a business closed on Shabbat, a time (of the day or around
--               a shift) opens nothing on Friday after candle lighting, opens
--               at havdalah on Saturday with as long as it would have had, and
--               one due after candle lighting on Friday is due then.
--               @domain/list-openings says the same for the editor's time not
--               yet saved; public.next_list_openings gives the editor the
--               saved ones', leaving out a day that already has its list.
--   the tick    private.lists_tick, every minute (the job `lists`, pure SQL,
--               no secret) and at the end of a demo reset: for each business
--               with lists on, in its own block so one business's error never
--               stops another's, it opens what has opened by now and is not
--               more than 12 hours past its due time (once: the unique key of
--               a schedule's day), to the time's recipient or, when nobody is
--               there to take it (an empty or unpublished shift, someone who
--               left, a removed department), to the managers; closes as
--               missed a list whose next one opened or that is 24 hours past
--               its due time, unless it was opened again by hand; and marks
--               reminders and late lists once each.
--               A business closed on Shabbat gets nothing of this during it.
--               Locally and in CI the job is off (supabase/seed.sql): the
--               tests run the tick at the times they choose.
--   lines       private.notify_for_lists (L1's), with the reminder
--               (`lists.due`, to the list's people, pushed only until it is
--               due), the late line (`lists.late`, to them, and
--               `lists.late_team` to the list managers while
--               tellManagersWhenLate is on) and a reading outside its range
--               (`lists.out_of_range`, to the list managers, with the reading
--               and its range): set_list_item logs one when a reading moves
--               outside it.
--   demo        private.seed_demo_lists ticks too where the definition says
--               "scheduledLists": true (the hosted ones, patched here, as
--               supabase/hosted-demo.sql says), after giving the demo's times
--               the age of a business that has had them all along, so today's
--               lists are there after a reset, some already late; the examples
--               it sends are of templates nothing opened today. Any other
--               definition (the local seed's, the tests') opens none, so no
--               browser or database test depends on the hour. Both hosted demo
--               businesses start again.

------------------------------------------------------------------------------
-- Two stamps the tick reads

-- From when a time's openings count. Every time there is now counts from this
-- migration: none of them ran before it, so the first tick opens nothing they
-- would have opened earlier (the catch-up of 12 hours is for an outage, not
-- for times that never ran). save_list_template and restore_list_template,
-- below, move it on.
alter table public.list_schedules
  add column opens_from timestamptz not null default now();

comment on column public.list_schedules.opens_from is
  'From when the time''s openings count: when it was saved, and again when its days or hours changed, it was switched back on, or its template came back. private.list_occurrences opens nothing before it.';

-- When a finished or cancelled list was opened again (public.reopen_list,
-- below). The tick never closes such a list as missed: a correction stays
-- open until someone finishes or cancels it.
alter table public.lists add column reopened_at timestamptz;

------------------------------------------------------------------------------
-- Shabbat

create table private.shabbat_times (
  -- A key of ISRAELI_CITIES (@domain/shabbat), as businesses.shabbat_city.
  city text not null,
  friday date not null check (extract(dow from friday) = 5),
  candle_lighting timestamptz not null,
  havdalah timestamptz not null,
  primary key (city, friday),
  check (havdalah > candle_lighting)
);

revoke all on private.shabbat_times from public, anon, authenticated;

comment on table private.shabbat_times is
  'Candle lighting and havdalah in each city a business''s Shabbat follows, a row a Friday, from @domain/shabbat-times (tooling/shabbat-table.test.ts keeps them equal). Read by private.shabbat_span.';

-- Israel's time, to the minute, with its offset then. Printed by
-- tooling/shabbat-table.test.ts (SHABBAT_TABLE=print), which checks each row.
insert into private.shabbat_times (city, friday, candle_lighting, havdalah)
