-- Whether Shabbat matters to the business's lists: its schedule is on and
-- closes on Shabbat (closedOnShabbat, true by default), as closesOnShabbat in
-- app/(app)/manage/manage.ts has it.
create function private.closes_on_shabbat(business uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.module_enabled(business, 'scheduling'::public.module_key)
    and coalesce(
      (
        select (bm.settings ->> 'closedOnShabbat')::boolean
        from public.business_modules bm
        where bm.business_id = business
          and bm.module_key = 'scheduling'::public.module_key
          and jsonb_typeof(bm.settings -> 'closedOnShabbat') = 'boolean'
      ),
      true
    )
$$;

-- Candle lighting to havdalah of the Shabbat a Friday or a Saturday belongs
-- to, in the business's city (Tel Aviv while it has none, or one no longer
-- listed, as @domain/shabbat reads it). Null on any other day, or past the
-- table's last Friday.
create function private.shabbat_span(business uuid, on_day date)
returns tstzrange
language sql
stable
security definer
set search_path = ''
as $$
  select tstzrange(st.candle_lighting, st.havdalah)
  from public.businesses b
  cross join lateral (
    select s.candle_lighting, s.havdalah
    from private.shabbat_times s
    where s.friday = case extract(dow from on_day)::integer
        when 5 then on_day
        when 6 then on_day - 1
      end
      and (s.city = b.shabbat_city or s.city = 'telAviv')
    order by coalesce(s.city = b.shabbat_city, false) desc
    limit 1
  ) st
  where b.id = business
$$;

------------------------------------------------------------------------------
-- When a time opens its lists

-- The lists a schedule opens from just after `from_time` up to and including
-- `to_time`, earliest first: the day each belongs to (the shift's day for a
-- shift), when it opens, when it is due, and the shift it followed. None for
-- a paused time or a removed template. The minute job and the editor's next
-- openings both read this, so they never disagree; @domain/list-openings is
-- the same rules for a time not yet saved.
create function private.list_occurrences(
  schedule uuid,
  from_time timestamptz,
  to_time timestamptz
)
returns table (occurs_on date, opens_at timestamptz, due_at timestamptz, shift_id uuid)
language sql
stable
security definer
set search_path = ''
as $$
  with sched as (
    select ls.id, ls.business_id, ls.days, ls.anchor, ls.shift_key, ls.opens_offset,
      ls.due_offset, ls.starts_on, ls.opens_from, b.timezone as tz,
      private.closes_on_shabbat(ls.business_id) as shabbat_closed
    from public.list_schedules ls
    join public.list_templates t
      on t.id = ls.template_id and t.business_id = ls.business_id and t.archived_at is null
    join public.businesses b on b.id = ls.business_id
    where ls.id = schedule
      and ls.active
      and from_time < to_time
      and (ls.anchor = 'day' or private.has_shift_pattern(ls.business_id, ls.shift_key))
  ),
  -- A time of the day: each local day around the window it runs on, its
  -- minutes read on the business's clock.
  by_day as (
    select g.on_day, sc.opens_offset, sc.due_offset,
      (g.on_day + make_interval(mins => sc.opens_offset)) at time zone sc.tz as raw_opens,
      (g.on_day + make_interval(mins => sc.due_offset)) at time zone sc.tz as raw_due
    from sched sc
    cross join lateral (
      select (from_time at time zone sc.tz)::date - 1 + k as on_day
      from generate_series(
        0,
        (to_time at time zone sc.tz)::date - (from_time at time zone sc.tz)::date + 2
      ) as k
    ) g
    where sc.anchor = 'day'
      and extract(dow from g.on_day)::smallint = any (sc.days)
      and g.on_day >= sc.starts_on
  ),
  -- A time the spring change skips opens an hour later, which can pass a due
  -- time just after the change: then it has as long as it would have.
  day_fixed as (
    select bd.on_day, bd.raw_opens as opens,
      case when bd.raw_due <= bd.raw_opens
        then bd.raw_opens + make_interval(mins => bd.due_offset - bd.opens_offset)
        else bd.raw_due
      end as due,
      null::uuid as shift
    from by_day bd
  ),
  -- A time that follows a shift: minutes around the start or the end (the
  -- next day when it ends at or before its start) of each published shift of
  -- its pattern, on the days it runs, one a day (the earliest).
  by_shift as (
    select distinct on (ss.day) ss.day as on_day,
      a.anchor_at + make_interval(mins => sc.opens_offset) as opens,
      a.anchor_at + make_interval(mins => sc.due_offset) as due,
      ss.id as shift
    from sched sc
    join public.schedule_shifts ss
      on ss.business_id = sc.business_id and ss.pattern_key = sc.shift_key
    cross join lateral (
      select case sc.anchor
        when 'shift_start' then (ss.day + ss.starts_at) at time zone sc.tz
        else (ss.day + case when ss.ends_at <= ss.starts_at then 1 else 0 end + ss.ends_at)
          at time zone sc.tz
      end as anchor_at
    ) a
    where sc.anchor <> 'day'
      and ss.day between (from_time at time zone sc.tz)::date - 2
        and (to_time at time zone sc.tz)::date + 2
      and extract(dow from ss.day)::smallint = any (sc.days)
      and ss.day >= sc.starts_on
      and private.shift_published(ss.id)
    order by ss.day, a.anchor_at, ss.id
  ),
  -- Every opening, with the Shabbat of the day it opens on, for a business
  -- closed on it (a time of the day and one around a shift alike).
  spanned as (
    select o.on_day, o.opens, o.due, o.shift,
      extract(dow from (o.opens at time zone sc.tz))::integer as weekday,
      case when sc.shabbat_closed
        then private.shabbat_span(sc.business_id, (o.opens at time zone sc.tz)::date)
      end as span
    from (
      select df.on_day, df.opens, df.due, df.shift from day_fixed df
      union all
      select bs.on_day, bs.opens, bs.due, bs.shift from by_shift bs
    ) o
    cross join sched sc
  ),
  -- Shabbat: nothing on Friday after candle lighting; on Saturday before
  -- havdalah, at havdalah with the same length; due at candle lighting when
  -- it opens before it on Friday and is due after.
  kept as (
    select sp.on_day,
      case when sp.span @> sp.opens and sp.weekday = 6
        then upper(sp.span) else sp.opens
      end as opens,
      case
        when sp.span @> sp.opens and sp.weekday = 6
          then upper(sp.span) + (sp.due - sp.opens)
        when sp.weekday = 5
          and sp.opens < lower(sp.span) and sp.due > lower(sp.span)
          then lower(sp.span)
        else sp.due
      end as due,
      sp.shift
    from spanned sp
    where not coalesce(sp.span @> sp.opens and sp.weekday = 5, false)
  )
  select k.on_day, k.opens, k.due, k.shift
  from kept k
  cross join sched sc
  where k.opens > from_time
    and k.opens <= to_time
    -- Saved, changed or switched on after its own time today: it starts with
    -- the next one.
    and k.opens >= sc.opens_from
  order by k.opens
$$;

------------------------------------------------------------------------------
-- The tick

-- One business's minute, at `at_time`: opens the lists its times have opened
-- by then and that are not more than 12 hours past their due time, closes as
-- missed what nobody did, and marks reminders and late lists, each once. A
-- business closed on Shabbat gets none of it during Shabbat (missed lists
-- tell nobody, and still close). Logged with no actor; the lines hang on the
-- log. Returns how many lists it opened.
create function private.lists_tick_business(business uuid, at_time timestamptz)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  tz text;
  lists_settings jsonb;
  remind_before integer;
  late_after integer;
  in_shabbat boolean;
  due_one record;
  gone record;
  soon record;
  late_one record;
  lid uuid;
  people uuid[];
  to_kind text;
  to_department uuid;
  to_role public.member_role;
  to_shift uuid;
  locked boolean := false;
  opened integer := 0;
begin
  select b.timezone into tz from public.businesses b where b.id = business;
  if not found then
    return 0;
  end if;
  lists_settings := private.list_settings(business);
  remind_before := coalesce((lists_settings ->> 'remindBeforeMinutes')::integer, 30);
  late_after := coalesce((lists_settings ->> 'lateAfterMinutes')::integer, 15);
  in_shabbat := private.closes_on_shabbat(business)
    and coalesce(
      private.shabbat_span(business, (at_time at time zone tz)::date) @> at_time,
      false
    );

  -- 1. What has opened by now, once each (the unique key of a schedule's day).
  if not in_shabbat then
    for due_one in
      select ls.id as schedule, ls.template_id as template, t.name as template_name,
        t.note as template_note, t.from_department as asking, t.asks_quantities as asks,
        ls.anchor as anchor_kind, ls.shift_key as pattern, ls.recipient_kind as for_kind,
        ls.recipient_user as for_user, ls.recipient_department as for_department,
        ls.recipient_shift as for_shift, ls.recipient_role as for_role,
        o.occurs_on as on_day, o.opens_at as opens, o.due_at as due,
        o.shift_id as anchor_shift
      from public.list_schedules ls
      join public.list_templates t
        on t.id = ls.template_id and t.business_id = ls.business_id and t.archived_at is null
      cross join lateral private.list_occurrences(
        ls.id, at_time - interval '36 hours', at_time
      ) as o
      where ls.business_id = business
        and ls.active
        and o.due_at > at_time - interval '12 hours'
        and not exists (
          select 1 from public.lists l
          where l.schedule_id = ls.id and l.occurs_on = o.occurs_on
        )
      order by o.opens_at, ls.id
    loop
      if not locked then
        -- Under the business's lock, as send_list counts, so the cap holds.
        perform 1 from public.businesses b where b.id = business for no key update;
        locked := true;
      end if;
      if (
        select count(*) from public.lists l
        where l.business_id = business and l.status = 'open'
      ) >= 500 then
        raise warning 'Business % keeps 500 open lists: its times wait', business;
        exit;
      end if;

      to_kind := due_one.for_kind;
      to_department := null;
      to_role := null;
      to_shift := null;
      people := '{}'::uuid[];
      case due_one.for_kind
      when 'person' then
        people := array(
          select m.user_id
          from public.memberships m
          where m.business_id = business
            and m.user_id = due_one.for_user
            and m.active
            and private.is_staff_role(m.role)
        );
      when 'department' then
        if exists (
          select 1 from public.departments d
          where d.id = due_one.for_department
            and d.business_id = business
            and d.archived_at is null
        ) then
          to_department := due_one.for_department;
        end if;
      when 'shift' then
        -- The shift it follows, or that day's published shift of the pattern.
        if due_one.anchor_kind <> 'day' and due_one.for_shift = due_one.pattern then
          to_shift := due_one.anchor_shift;
        else
          select ss.id into to_shift
          from public.schedule_shifts ss
          where ss.business_id = business
            and ss.pattern_key = due_one.for_shift
            and ss.day = due_one.on_day
            and private.shift_published(ss.id)
          order by ss.starts_at, ss.id
          limit 1;
        end if;
        people := array(
          select a.user_id
          from public.shift_assignments a
          join public.memberships m
            on m.business_id = business and m.user_id = a.user_id and m.active
            and private.is_staff_role(m.role)
          where a.shift_id = to_shift
          order by a.user_id
        );
      else
        to_role := due_one.for_role;
      end case;

      -- Nobody there to take it: the managers, so it is never lost.
      if (to_kind in ('person', 'shift') and cardinality(people) = 0)
        or (to_kind = 'department' and to_department is null)
        or (to_kind = 'role' and to_role is null) then
        to_kind := 'role';
        to_role := 'manager'::public.member_role;
        people := '{}'::uuid[];
      end if;

      lid := null;
      insert into public.lists (
        business_id, template_id, schedule_id, occurs_on, name, note, origin,
        recipient_kind, recipient_department, recipient_role, shift_id, shift,
        from_department, asks_quantities, opens_at, due_at
      )
      values (
        business, due_one.template, due_one.schedule, due_one.on_day,
        due_one.template_name, due_one.template_note, 'scheduled', to_kind,
        to_department, to_role, to_shift,
        case when to_shift is not null then private.shift_brief(to_shift) end,
        due_one.asking, due_one.asks, due_one.opens, due_one.due
      )
      on conflict (schedule_id, occurs_on) do nothing
      returning id into lid;
      if lid is null then
        continue;
      end if;

      insert into public.list_items (
        list_id, business_id, template_item_id, position, kind, label, hint, required,
        unit, min_value, max_value, requested
      )
      select lid, business, i.id, i.position, i.kind, i.label, i.hint, i.required,
        i.unit, i.min_value, i.max_value,
        case when due_one.asks and i.kind = 'check' then i.default_quantity end
      from public.list_template_items i
      where i.template_id = due_one.template
      order by i.position;

      insert into public.list_people (list_id, business_id, user_id)
      select lid, business, p.person from unnest(people) as p (person);

      insert into public.audit_log (business_id, actor_id, action, details)
      values (
        business, null::uuid, 'lists.open',
        jsonb_build_object(
          'list', lid,
          'schedule', due_one.schedule,
          'template', due_one.template,
          'name', due_one.template_name,
          'occurs_on', due_one.on_day
        )
      );
      opened := opened + 1;
    end loop;
  end if;

  -- 2. Missed: a scheduled list whose next one has opened, or still open 24
  --    hours after its due time. A daily list missed for a week leaves one
  --    open list, not seven. One opened again by hand (reopen_list) is a
  --    correction, which waits for whoever finishes or cancels it.
  for gone in
    update public.lists l
    set status = 'missed', closed_at = at_time
    where l.id in (
      select x.id
      from public.lists x
      where x.business_id = business
        and x.status = 'open'
        and x.origin = 'scheduled'
        and x.reopened_at is null
        and (
          x.due_at + interval '24 hours' <= at_time
          or exists (
            select 1 from public.lists newer
            where newer.business_id = business
              and newer.schedule_id = x.schedule_id
              and newer.occurs_on > x.occurs_on
              and newer.opens_at <= at_time
          )
        )
      for update skip locked
    )
    returning l.id, l.name
  loop
    insert into public.audit_log (business_id, actor_id, action, details)
    values (
      business, null::uuid, 'lists.missed',
      jsonb_build_object('list', gone.id, 'name', gone.name)
    );
  end loop;

  if in_shabbat then
    return opened;
  end if;

  -- 3. Due soon: once, `remindBeforeMinutes` before the due time, unless the
  --    list opened inside that window (its "sent" line says as much).
  if remind_before > 0 then
    for soon in
      update public.lists l
      set reminded_at = at_time
      where l.id in (
        select x.id
        from public.lists x
        where x.business_id = business
          and x.status = 'open'
          and x.due_at is not null
          and x.reminded_at is null
          and x.due_at - make_interval(mins => remind_before) <= at_time
          and at_time < x.due_at
          and x.opens_at < x.due_at - make_interval(mins => remind_before)
        for update skip locked
      )
      returning l.id, l.name, l.due_at
    loop
      insert into public.audit_log (business_id, actor_id, action, details)
      values (
        business, null::uuid, 'lists.due',
        jsonb_build_object('list', soon.id, 'name', soon.name, 'due_at', soon.due_at)
      );
    end loop;
  end if;

  -- 4. Late: once, `lateAfterMinutes` after the due time.
  for late_one in
    update public.lists l
    set late_at = at_time
    where l.id in (
      select x.id
      from public.lists x
      where x.business_id = business
        and x.status = 'open'
        and x.due_at is not null
        and x.late_at is null
        and x.due_at + make_interval(mins => late_after) <= at_time
      for update skip locked
    )
    returning l.id, l.name, l.due_at
  loop
    insert into public.audit_log (business_id, actor_id, action, details)
    values (
      business, null::uuid, 'lists.late',
      jsonb_build_object('list', late_one.id, 'name', late_one.name, 'due_at', late_one.due_at)
    );
  end loop;

  return opened;
end;
$$;

-- The minute job (`lists`, below), the demo reset (`for_business`) and the
-- tests (at the times they choose): every business with lists on, or only
-- `for_business`, each in its own block, so a business that fails (a reset
-- removing it this minute, a row it can't keep) leaves the others' lists
-- opening. Returns how many lists it opened.
create function private.lists_tick(
  at_time timestamptz default now(),
  for_business uuid default null
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  each_business uuid;
  opened integer := 0;
begin
  for each_business in
    select b.id
    from public.businesses b
    where (for_business is null or b.id = for_business)
      and private.module_enabled(b.id, 'lists'::public.module_key)
    order by b.id
  loop
    begin
      opened := opened + private.lists_tick_business(each_business, at_time);
    exception when others then
      raise warning 'Lists did not tick for business %: %', each_business, sqlerrm;
    end;
  end loop;
  return opened;
end;
$$;

-- Every minute, as the database's owner. supabase/seed.sql switches it off
-- locally and in CI, as it does the notifications' jobs. The times there are
-- already count from this migration (opens_from's default, above), so the
-- first minute catches up on nothing they never ran.
select cron.schedule('lists', '* * * * *', $$select private.lists_tick()$$);

------------------------------------------------------------------------------
-- The editor's next openings

-- For the editor ("נשלחת מחר ב-08:30"): the next three openings of each of
-- the template's times after `at_time`, in their order, from the same
-- private.list_occurrences the minute job opens lists by, without a day that
-- already has its list (the job opens one a day). A paused time has none.
-- For list managers and the team, with the secret key, for `actor`.
--
--   [{schedule: id, openings: [{occursOn, opensAt, dueAt}]}]
create function public.next_list_openings(
  actor uuid,
  template uuid,
  at_time timestamptz default now()
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  t public.list_templates%rowtype;
begin
  select x.* into t from public.list_templates x where x.id = template;
  if not found or not (
    exists (
      select 1 from public.memberships m
      where m.business_id = t.business_id and m.user_id = actor and m.active
    )
    or exists (select 1 from public.platform_staff ps where ps.user_id = actor)
  ) then
    raise exception 'Unknown template' using errcode = 'P0002';
  end if;
  if not (
    private.can_manage_lists(t.business_id, actor)
    or private.can_edit_settings(t.business_id, actor)
  ) then
    raise exception 'List managers and the team only' using errcode = '42501';
  end if;
  perform private.lists_on(t.business_id);

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'schedule', ls.id,
          'openings', coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'occursOn', o.occurs_on,
                  'opensAt', o.opens_at,
                  'dueAt', o.due_at
                )
                order by o.opens_at
              )
              from (
                select n.occurs_on, n.opens_at, n.due_at
                from private.list_occurrences(
                  ls.id, at_time, at_time + interval '22 days'
                ) as n
                where not exists (
                  select 1 from public.lists l
                  where l.schedule_id = ls.id and l.occurs_on = n.occurs_on
                )
                order by n.opens_at
                limit 3
              ) o
            ),
            '[]'::jsonb
          )
        )
        order by ls.position, ls.id
      )
      from public.list_schedules ls
      where ls.template_id = t.id
    ),
    '[]'::jsonb
  );
end;
$$;

------------------------------------------------------------------------------
-- Saving a time, bringing a template back, opening a list again

-- save_list_template of 20261109000600_lists.sql, which now moves a time's
-- opens_from on to now when its days or hours change or it is switched back
-- on, so a time already gone by today opens tomorrow rather than late now.
-- Who it goes to and its place leave it as it was. A new time takes now from
-- the column's default.
create or replace function public.save_list_template(
  actor uuid,
  business uuid,
  template jsonb,
  seen_version integer default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  tz text;
  existing public.list_templates%rowtype;
  tid uuid;
  new_version integer;
  is_new boolean;
  new_name text;
  new_note text;
  rk text;
  rd uuid;
  rs text;
  rr public.member_role;
  asking uuid;
  asks boolean;
  wanted_items jsonb;
  wanted_schedules jsonb;
  entry jsonb;
  place integer;
  entry_id uuid;
  f record;
  s record;
  kept uuid[] := '{}'::uuid[];
  item_count integer;
  schedule_count integer;
begin
  if not (
    private.can_manage_lists(business, actor) or private.can_edit_settings(business, actor)
  ) then
    raise exception 'List managers and the team only' using errcode = '42501';
  end if;
  select b.timezone into tz from public.businesses b where b.id = business;
  if not found then
    raise exception 'Unknown business' using errcode = 'P0002';
  end if;
  perform private.lists_on(business);

  if jsonb_typeof(template) is distinct from 'object' then
    raise exception 'A template must be an object' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(template) as k (field)
    where k.field not in (
      'id', 'name', 'note', 'recipient', 'fromDepartment', 'asksQuantities', 'items', 'schedules'
    )
  ) then
    raise exception 'A template has a name, a note, a recipient, an asking department, items and schedules'
      using errcode = '22023';
  end if;

  new_name := private.json_text(template -> 'name', 60, 'The name');
  if new_name is null then
    raise exception 'A template needs a name' using errcode = '22023';
  end if;
  new_note := private.json_text(template -> 'note', 300, 'The note');

  if coalesce(jsonb_typeof(template -> 'recipient'), 'null') <> 'null' then
    select r.to_kind, r.to_department, r.to_shift, r.to_role
    into rk, rd, rs, rr
    from private.list_recipient(
      business, template -> 'recipient', array['department', 'shift', 'role']
    ) as r;
  end if;

  asking := private.json_uuid(template -> 'fromDepartment', 'The department that asks');
  if asking is not null then
    if not exists (
      select 1 from public.departments d
      where d.id = asking and d.business_id = business and d.archived_at is null
    ) then
      raise exception 'Not a department of this business' using errcode = '22023';
    end if;
    if rk is distinct from 'department' or rd = asking then
      raise exception 'An order goes from its department to another one'
        using errcode = '22023';
    end if;
  end if;
  asks := private.json_bool(template -> 'asksQuantities', false, 'Asks for quantities');

  wanted_items := template -> 'items';
  if jsonb_typeof(wanted_items) is distinct from 'array' then
    raise exception 'A template has from 1 to 60 items' using errcode = '22023';
  end if;
  if jsonb_array_length(wanted_items) not between 1 and 60 then
    raise exception 'A template has from 1 to 60 items' using errcode = '22023';
  end if;
  wanted_schedules := coalesce(template -> 'schedules', '[]'::jsonb);
  if jsonb_typeof(wanted_schedules) = 'null' then
    wanted_schedules := '[]'::jsonb;
  end if;
  if jsonb_typeof(wanted_schedules) <> 'array' then
    raise exception 'A template has at most 7 schedules' using errcode = '22023';
  end if;
  if jsonb_array_length(wanted_schedules) > 7 then
    raise exception 'A template has at most 7 schedules' using errcode = '22023';
  end if;

  tid := private.json_uuid(template -> 'id', 'The template''s id');
  if tid is null then
    -- Under the business's lock, so two saves at once can't pass the cap.
    perform 1 from public.businesses b where b.id = business for no key update;
    if (
      select count(*) from public.list_templates t
      where t.business_id = business and t.archived_at is null
    ) >= 100 then
      raise exception 'A business keeps at most 100 lists' using errcode = '22023';
    end if;
    insert into public.list_templates (
      business_id, name, note, recipient_kind, recipient_department, recipient_shift,
      recipient_role, from_department, asks_quantities, position, created_by, updated_by
    )
    values (
      business, new_name, new_note, rk, rd, rs, rr, asking, asks,
      (
        select coalesce(max(t.position) + 1, 0)
        from public.list_templates t
        where t.business_id = business
      )::smallint,
      actor, actor
    )
    returning id, version into tid, new_version;
    is_new := true;
  else
    select t.* into existing
    from public.list_templates t
    where t.id = tid and t.business_id = business
    for update;
    if not found then
      raise exception 'Unknown template' using errcode = 'P0002';
    end if;
    if existing.archived_at is not null then
      raise exception 'The template was removed' using errcode = '55000';
    end if;
    if seen_version is not null and seen_version <> existing.version then
      raise exception 'The template changed since it was read' using errcode = '40001';
    end if;
    new_version := existing.version + 1;
    update public.list_templates t
    set name = new_name,
      note = new_note,
      recipient_kind = rk,
      recipient_department = rd,
      recipient_shift = rs,
      recipient_role = rr,
      from_department = asking,
      asks_quantities = asks,
      version = new_version,
      updated_by = actor
    where t.id = tid;
    is_new := false;
  end if;

  for entry, place in
    select e.value, e.ordinality::integer
    from jsonb_array_elements(wanted_items) with ordinality as e (value, ordinality)
  loop
    select * into f from private.list_item_fields(entry, true);
    entry_id := private.json_uuid(entry -> 'id', 'An item''s id');
    if entry_id = any (kept) then
      raise exception 'An item is there twice' using errcode = '22023';
    end if;
    if entry_id is null then
      insert into public.list_template_items (
        template_id, business_id, position, kind, label, hint, required, unit,
        min_value, max_value, default_quantity
      )
      values (
        tid, business, (place - 1)::smallint, f.item_kind, f.item_label, f.item_hint,
        f.item_required, f.item_unit, f.item_min, f.item_max, f.item_quantity
      )
      returning id into entry_id;
    else
      update public.list_template_items i
      set position = (place - 1)::smallint,
        kind = f.item_kind,
        label = f.item_label,
        hint = f.item_hint,
        required = f.item_required,
        unit = f.item_unit,
        min_value = f.item_min,
        max_value = f.item_max,
        default_quantity = f.item_quantity
      where i.id = entry_id and i.template_id = tid;
      if not found then
        raise exception 'Not an item of this template' using errcode = '22023';
      end if;
    end if;
    kept := kept || entry_id;
  end loop;
  delete from public.list_template_items i
  where i.template_id = tid and i.id <> all (kept);
  item_count := cardinality(kept);

  kept := '{}'::uuid[];
  for entry, place in
    select e.value, e.ordinality::integer
    from jsonb_array_elements(wanted_schedules) with ordinality as e (value, ordinality)
  loop
    select * into s from private.list_schedule_fields(business, entry);
    entry_id := private.json_uuid(entry -> 'id', 'A schedule''s id');
    if entry_id = any (kept) then
      raise exception 'A schedule is there twice' using errcode = '22023';
    end if;
    if entry_id is null then
      insert into public.list_schedules (
        template_id, business_id, position, days, anchor, shift_key, opens_offset,
        due_offset, recipient_kind, recipient_user, recipient_department,
        recipient_shift, recipient_role, active, starts_on
      )
      values (
        tid, business, (place - 1)::smallint, s.at_days, s.at_anchor, s.at_shift,
        s.at_opens, s.at_due, s.for_kind, s.for_user, s.for_department, s.for_shift,
        s.for_role, s.is_active, (now() at time zone tz)::date
      )
      returning id into entry_id;
    else
      -- Edited in place, keeping its id, so the day's list never opens twice.
      update public.list_schedules ls
      set position = (place - 1)::smallint,
        days = s.at_days,
        anchor = s.at_anchor,
        shift_key = s.at_shift,
        opens_offset = s.at_opens,
        due_offset = s.at_due,
        recipient_kind = s.for_kind,
        recipient_user = s.for_user,
        recipient_department = s.for_department,
        recipient_shift = s.for_shift,
        recipient_role = s.for_role,
        active = s.is_active,
        -- Other days or hours, or on again: it counts from now.
        opens_from = case
          when not (ls.days @> s.at_days and ls.days <@ s.at_days)
            or ls.anchor is distinct from s.at_anchor
            or ls.shift_key is distinct from s.at_shift
            or ls.opens_offset <> s.at_opens
            or ls.due_offset <> s.at_due
            or (not ls.active and s.is_active)
            then now()
          else ls.opens_from
        end
      where ls.id = entry_id and ls.template_id = tid;
      if not found then
        raise exception 'Not a schedule of this template' using errcode = '22023';
      end if;
    end if;
    kept := kept || entry_id;
  end loop;
  delete from public.list_schedules ls
  where ls.template_id = tid and ls.id <> all (kept);
  schedule_count := cardinality(kept);

  insert into public.audit_log (business_id, actor_id, action, details)
  values (
    business, actor, 'lists.template.save',
    jsonb_build_object(
      'template', tid,
      'name', new_name,
      'created', is_new,
      'items', item_count,
      'schedules', schedule_count
    )
  );

  return jsonb_build_object('id', tid, 'version', new_version);
end;
$$;

-- restore_list_template of 20261109000600_lists.sql, which now moves the
-- template's times' opens_from on to now: nothing it would have opened while
-- it was removed opens late when it comes back.
create or replace function public.restore_list_template(actor uuid, template uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.list_templates%rowtype;
begin
  select x.* into t from public.list_templates x where x.id = template for update;
  if not found or not (
    exists (
      select 1 from public.memberships m
      where m.business_id = t.business_id and m.user_id = actor and m.active
    )
    or exists (select 1 from public.platform_staff ps where ps.user_id = actor)
  ) then
    raise exception 'Unknown template' using errcode = 'P0002';
  end if;
  if not (
    private.can_manage_lists(t.business_id, actor)
    or private.can_edit_settings(t.business_id, actor)
  ) then
    raise exception 'List managers and the team only' using errcode = '42501';
  end if;
  perform private.lists_on(t.business_id);
  if t.archived_at is null then
    return;
  end if;
  -- Under the business's lock, as in save_list_template.
  perform 1 from public.businesses b where b.id = t.business_id for no key update;
  if (
    select count(*) from public.list_templates x
    where x.business_id = t.business_id and x.archived_at is null
  ) >= 100 then
    raise exception 'A business keeps at most 100 lists' using errcode = '22023';
  end if;

  update public.list_templates x
  set archived_at = null, version = t.version + 1, updated_by = actor
  where x.id = t.id;
  update public.list_schedules ls
  set opens_from = now()
  where ls.template_id = t.id;

  insert into public.audit_log (business_id, actor_id, action, details)
  values (
    t.business_id, actor, 'lists.template.restore',
    jsonb_build_object('template', t.id, 'name', t.name)
  );
end;
$$;

-- reopen_list of 20261109000600_lists.sql, which now stamps the list
-- (reopened_at), so the tick never closes a correction as missed.
create or replace function public.reopen_list(
  actor uuid,
  list uuid,
  at_time timestamptz default now()
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  l public.lists%rowtype;
begin
  select x.* into l from public.lists x where x.id = list for update;
  if not found or not exists (
    select 1 from public.memberships m
    where m.business_id = l.business_id and m.user_id = actor and m.active
  ) then
    raise exception 'Unknown list' using errcode = 'P0002';
  end if;
  perform private.lists_on(l.business_id);
  if l.status not in ('finished', 'cancelled') then
    raise exception 'Only a finished or cancelled list opens again' using errcode = '55000';
  end if;
  if not (
    private.can_manage_lists(l.business_id, actor)
    or (
      l.status = 'finished'
      and l.finished_by = actor
      and at_time <= l.finished_at + interval '5 minutes'
    )
    or (
      l.status = 'cancelled'
      and l.closed_by = actor
      and at_time <= l.closed_at + interval '5 minutes'
    )
  ) then
    raise exception 'Only a list manager opens it again after 5 minutes'
      using errcode = '42501';
  end if;
  -- The open-lists cap holds here too, under the business's lock as in send_list.
  perform 1 from public.businesses b where b.id = l.business_id for no key update;
  if (
    select count(*) from public.lists x
    where x.business_id = l.business_id and x.status = 'open'
  ) >= 500 then
    raise exception 'A business keeps at most 500 open lists' using errcode = '22023';
  end if;

  update public.lists x
  set status = 'open',
    finished_at = null,
    finished_by = null,
    closed_at = null,
    closed_by = null,
    reopened_at = at_time
  where x.id = l.id;

  insert into public.audit_log (business_id, actor_id, action, details)
  values (
    l.business_id, actor, 'lists.reopen',
    jsonb_build_object('list', l.id, 'name', l.name, 'was', l.status)
  );
end;
$$;

------------------------------------------------------------------------------
-- A reading outside its range

-- set_list_item of 20261109000600_lists.sql, and one more row: a reading that
-- moves outside its item's range (it was inside, or empty) is logged as
-- `lists.out_of_range`, which tells the list managers.
create or replace function public.set_list_item(
  actor uuid,
  item uuid,
  result jsonb,
  at_time timestamptz default now()
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  it public.list_items%rowtype;
  l public.lists%rowtype;
  new_checked boolean;
  new_reading numeric;
  new_answer text;
  new_given integer;
  new_comment text;
  is_done boolean;
  progress jsonb;
begin
  select i.* into it from public.list_items i where i.id = item;
  if not found then
    raise exception 'Unknown item' using errcode = 'P0002';
  end if;
  -- The list first, so a finish waits for this and this for a finish.
  select x.* into l from public.lists x where x.id = it.list_id for update;
  if not exists (
    select 1 from public.memberships m
    where m.business_id = l.business_id and m.user_id = actor and m.active
  ) then
    raise exception 'Unknown item' using errcode = 'P0002';
  end if;
  perform private.lists_on(l.business_id);
  if not (private.holds_list(l.id, actor) or private.can_manage_lists(l.business_id, actor)) then
    raise exception 'The list is not yours to fill' using errcode = '42501';
  end if;
  if l.status <> 'open' then
    raise exception 'The list is closed' using errcode = '55000';
  end if;
  select i.* into it from public.list_items i where i.id = item for update;

  if result is not null and jsonb_typeof(result) <> 'null' then
    if jsonb_typeof(result) <> 'object' then
      raise exception 'A result must be an object' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_object_keys(result) as k (field)
      where k.field not in ('checked', 'reading', 'answer', 'given', 'comment')
        or (it.kind = 'check' and k.field in ('reading', 'answer'))
        or (it.kind = 'number' and k.field in ('checked', 'answer', 'given'))
        or (it.kind = 'note' and k.field in ('checked', 'reading', 'given'))
        or (it.kind = 'photo' and k.field <> 'comment')
    ) then
      raise exception 'Not a result for this item' using errcode = '22023';
    end if;
    new_comment := private.json_text(result -> 'comment', 200, 'The comment');
    case it.kind
    when 'check' then
      new_checked := private.json_bool(result -> 'checked', false, 'Checked');
      new_given := private.json_int(result -> 'given', 0, 9999, 'How many were given');
      if new_given is not null and not l.asks_quantities then
        raise exception 'Only orders say how many were given' using errcode = '22023';
      end if;
      if new_given is not null then
        new_checked := true;
      elsif new_checked and l.asks_quantities then
        new_given := it.requested;
      end if;
      if not new_checked then
        new_checked := null;
      end if;
    when 'number' then
      new_reading := private.json_num(result -> 'reading', -100000, 100000, 'The reading');
    when 'note' then
      new_answer := private.json_text(result -> 'answer', 500, 'The answer');
    else
      -- Photos are set by the server after an upload (L6); a comment only here.
      null;
    end case;
  end if;

  is_done := case it.kind
    when 'check' then coalesce(new_checked, false) or new_given is not null
    when 'number' then new_reading is not null
    when 'note' then new_answer is not null
    else it.photo_path is not null
  end;

  update public.list_items i
  set checked = new_checked,
    reading = new_reading,
    answer = new_answer,
    given = new_given,
    comment = new_comment,
    done = is_done,
    done_by = case
      when it.kind = 'photo' then it.done_by
      when is_done then actor
    end,
    done_at = case
      when it.kind = 'photo' then it.done_at
      when is_done then at_time
    end
  where i.id = item;

  -- Outside its range now, and it wasn't before: the list managers hear.
  if it.kind = 'number'
    and new_reading is not null
    and (
      (it.min_value is not null and new_reading < it.min_value)
      or (it.max_value is not null and new_reading > it.max_value)
    )
    and not coalesce(
      (it.min_value is not null and it.reading < it.min_value)
        or (it.max_value is not null and it.reading > it.max_value),
      false
    ) then
    insert into public.audit_log (business_id, actor_id, action, details)
    values (
      l.business_id, actor, 'lists.out_of_range',
      jsonb_build_object(
        'list', l.id,
        'item', it.id,
        'name', l.name,
        'label', it.label,
        'reading', new_reading,
        'min', it.min_value,
        'max', it.max_value,
        'unit', it.unit
      )
    );
  end if;

  select jsonb_build_object(
    'done', count(*) filter (where i.done),
    'total', count(*),
    'required', count(*) filter (where i.required),
    'requiredLeft', count(*) filter (where i.required and not i.done)
  )
  into progress
  from public.list_items i
  where i.list_id = l.id;
  return progress;
end;
$$;

------------------------------------------------------------------------------
-- What each log row tells

-- private.notify_for_lists of 20261109000600_lists.sql, with L4's rows:
--
--   lists.send,       `lists.sent` to the people the list is for now, the
--   lists.open        actor left out (`list:<id>`).
--   lists.due         `lists.due` to them, once, pushed only until it is due
--                     (`list.due:<id>`).
--   lists.late        `lists.late` to them, once (`list.late:<id>`), and while
--                     tellManagersWhenLate is on `lists.late_team` to the list
--                     managers who don't hold it (`list.late_team:<id>`).
--   lists.out_of_range  `lists.out_of_range` to the list managers, the reader
--                     left out (`list.range:<item>`), with the item's label,
--                     the reading, its range and its unit.
--   lists.finish      settles the list's lines, and, while tellWhenFinished is
--                     on, `lists.finished` to whoever sent it and the
--                     department that asked, the finisher left out.
--   lists.cancel,     settle the list's lines.
--   lists.missed
--   lists.reopen      `lists.sent` again, unread, to the people it is for, and
--                     settles the finished line.
--
-- The facts are ids, the list's name, an item's label and a reading with its
-- range, all of which the reader may see in the app; never the note.
-- `fromDepartment`, not `from`, which the inbox reads as a person.
create or replace function private.notify_for_lists(entry public.audit_log)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  b uuid := entry.business_id;
  l public.lists%rowtype;
  facts jsonb;
begin
  select x.* into l
  from public.lists x
  where x.id = (entry.details ->> 'list')::uuid and x.business_id = b;
  if not found then
    return;
  end if;
  facts := jsonb_build_object(
    'list', l.id,
    'name', l.name,
    'due', l.due_at,
    'department', l.recipient_department,
    'fromDepartment', l.from_department
  );

  case entry.action
  when 'lists.send', 'lists.open', 'lists.reopen' then
    perform private.notify(
      b, private.list_holders(l.id), 'lists.sent', facts,
      entry.actor_id, 'lists', 'worker', 'list:' || l.id
    );
    if entry.action = 'lists.reopen' then
      perform private.resolve_notifications(b, 'list.finished:' || l.id);
    end if;

  when 'lists.due' then
    perform private.notify(
      b, private.list_holders(l.id), 'lists.due', facts,
      entry.actor_id, 'lists', 'worker', 'list.due:' || l.id,
      realert => false, push_until => l.due_at
    );

  when 'lists.late' then
    perform private.notify(
      b, private.list_holders(l.id), 'lists.late', facts,
      entry.actor_id, 'lists', 'worker', 'list.late:' || l.id,
      realert => false
    );
    if coalesce(private.list_setting(b, 'tellManagersWhenLate')::boolean, true) then
      perform private.notify(
        b, private.list_managers(b), 'lists.late_team', facts,
        entry.actor_id, 'lists', 'worker', 'list.late_team:' || l.id,
        realert => false, leave_out => private.list_holders(l.id)
      );
    end if;

  when 'lists.out_of_range' then
    perform private.notify(
      b, private.list_managers(b), 'lists.out_of_range',
      facts || jsonb_build_object(
        'item', entry.details -> 'item',
        'label', entry.details -> 'label',
        'reading', entry.details -> 'reading',
        'min', entry.details -> 'min',
        'max', entry.details -> 'max',
        'unit', entry.details -> 'unit'
      ),
      entry.actor_id, 'lists', 'worker', 'list.range:' || (entry.details ->> 'item')
    );

  when 'lists.finish' then
    perform private.resolve_notifications(b, 'list:' || l.id);
    perform private.resolve_notifications(b, 'list.due:' || l.id);
    perform private.resolve_notifications(b, 'list.late:' || l.id);
    perform private.resolve_notifications(b, 'list.late_team:' || l.id);
    if coalesce(private.list_setting(b, 'tellWhenFinished')::boolean, true) then
      perform private.notify(
        b,
        array[l.sent_by] || array(
          select dm.user_id from public.department_members dm
          where dm.department_id = l.from_department
        ),
        'lists.finished', facts,
        entry.actor_id, 'lists', 'worker', 'list.finished:' || l.id
      );
    end if;

  when 'lists.cancel', 'lists.missed' then
    perform private.resolve_notifications(b, 'list:' || l.id);
    perform private.resolve_notifications(b, 'list.due:' || l.id);
    perform private.resolve_notifications(b, 'list.late:' || l.id);
    perform private.resolve_notifications(b, 'list.late_team:' || l.id);

  else
    null;
  end case;
end;
$$;

------------------------------------------------------------------------------
-- Demo businesses

-- private.seed_demo_lists of 20261109000700_lists_on.sql, with the demo's own
-- times first, where the definition says "scheduledLists": true (the hosted
-- ones): given the age of a business that has had them all along (the reset
-- made them a moment ago, and nothing opens before a time's opens_from), then
-- ticked, so today's lists are there, some already late, and the minute job
-- keeps them coming. Any other definition (the local seed's, the tests')
-- opens none: its tests open lists at times they choose. The two examples,
-- sent as the demo's manager, are of templates nothing opened today. Whatever
-- goes wrong here, the reset still stands.
create or replace function private.seed_demo_lists(business uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  def jsonb;
  sender uuid;
  filler uuid;
  first_list public.list_templates%rowtype;
  second_list public.list_templates%rowtype;
  sent uuid;
  done_item uuid;
begin
  if not private.module_enabled(business, 'lists'::public.module_key) then
    return;
  end if;

  begin
    select d.definition into def
    from private.demo_businesses d
    where d.business_id = business;

    if coalesce((def ->> 'scheduledLists')::boolean, false) then
      update public.list_schedules ls
      set created_at = ls.created_at - interval '2 days',
        opens_from = ls.opens_from - interval '2 days',
        starts_on = ls.starts_on - 2
      where ls.business_id = business;
      perform private.lists_tick(now(), business);
    end if;

    select m.user_id into sender
    from jsonb_array_elements(
      case when jsonb_typeof(def -> 'people') = 'array' then def -> 'people' else '[]'::jsonb end
    ) with ordinality as person (value, ordinality)
    join public.memberships m
      on m.business_id = business
      and m.user_id::text = person.value ->> 'user_id'
      and m.active
    where m.role in ('manager', 'owner')
    order by (m.role = 'manager') desc, person.ordinality
    limit 1;
    if sender is null then
      return;
    end if;

    select t.* into first_list
    from public.list_templates t
    where t.business_id = business
      and t.archived_at is null
      and t.from_department is null
      and not exists (select 1 from public.lists x where x.template_id = t.id)
    order by t.position, t.key
    limit 1;
    if not found then
      return;
    end if;

    select m.user_id into filler
    from jsonb_array_elements(
      case when jsonb_typeof(def -> 'people') = 'array' then def -> 'people' else '[]'::jsonb end
    ) with ordinality as person (value, ordinality)
    join public.memberships m
      on m.business_id = business
      and m.user_id::text = person.value ->> 'user_id'
      and m.active
    where m.role = 'worker'
    order by coalesce(
      (first_list.recipient_kind = 'department' and exists (
        select 1 from public.department_members dm
        where dm.department_id = first_list.recipient_department and dm.user_id = m.user_id
      ))
      or (first_list.recipient_kind = 'role' and first_list.recipient_role = m.role),
      false
    ) desc, person.ordinality
    limit 1;

    if filler is not null then
      sent := public.send_list(
        sender, business,
        jsonb_build_object(
          'template', first_list.id,
          'recipient', jsonb_build_object('kind', 'person', 'user', filler)
        )
      );
      for done_item in
        select i.id from public.list_items i
        where i.list_id = sent and i.kind = 'check'
        order by i.position
        limit 2
      loop
        perform public.set_list_item(filler, done_item, '{"checked": true}'::jsonb);
      end loop;
    end if;

    select t.* into second_list
    from public.list_templates t
    where t.business_id = business
      and t.archived_at is null
      and t.from_department is null
      and t.id <> first_list.id
      and t.recipient_kind in ('department', 'role')
      and not exists (select 1 from public.lists x where x.template_id = t.id)
    order by t.position, t.key
    limit 1;
    if found then
      perform public.send_list(
        sender, business,
        jsonb_build_object(
          'template', second_list.id,
          'recipient', case second_list.recipient_kind
            when 'department' then jsonb_build_object(
              'kind', 'department', 'department', second_list.recipient_department
            )
            else jsonb_build_object('kind', 'role', 'role', second_list.recipient_role)
          end
        )
      );
    end if;
  exception when others then
    raise warning 'The demo''s example lists were not sent: %', sqlerrm;
  end;
end;
$$;

-- The hosted demo businesses open their scheduled lists (supabase/
-- hosted-demo.sql says the same, for the workflow's "demo" step), and start
-- again with today's. Locally the seed runs after the migrations and resets
-- its own, which open none.
update private.demo_businesses d
set definition = d.definition || '{"scheduledLists": true}'::jsonb
where d.business_id in (
  '10000000-0000-4000-b000-000000000001', '10000000-0000-4000-b000-000000000002'
);

select public.reset_demo_business(d.business_id)
from private.demo_businesses d
join public.businesses b on b.id = d.business_id
where d.business_id in (
  '10000000-0000-4000-b000-000000000001', '10000000-0000-4000-b000-000000000002'
);

------------------------------------------------------------------------------
-- Who may call what

-- The editor's next openings: the server's alone, for `actor`.
revoke execute on function public.next_list_openings(uuid, uuid, timestamptz)
  from public, anon, authenticated;
grant execute on function public.next_list_openings(uuid, uuid, timestamptz) to service_role;

-- Replaced above; their grants stay as before.
revoke execute on function public.set_list_item(uuid, uuid, jsonb, timestamptz)
  from public, anon, authenticated;
grant execute on function public.set_list_item(uuid, uuid, jsonb, timestamptz)
  to service_role;
revoke execute on function public.save_list_template(uuid, uuid, jsonb, integer)
  from public, anon, authenticated;
grant execute on function public.save_list_template(uuid, uuid, jsonb, integer)
  to service_role;
revoke execute on function public.restore_list_template(uuid, uuid)
  from public, anon, authenticated;
grant execute on function public.restore_list_template(uuid, uuid) to service_role;
revoke execute on function public.reopen_list(uuid, uuid, timestamptz)
  from public, anon, authenticated;
grant execute on function public.reopen_list(uuid, uuid, timestamptz) to service_role;

-- The rest run inside the functions, the job and the reset, as their owner.
revoke execute on function private.closes_on_shabbat(uuid) from public, anon, authenticated;
revoke execute on function private.shabbat_span(uuid, date) from public, anon, authenticated;
revoke execute on function private.list_occurrences(uuid, timestamptz, timestamptz)
  from public, anon, authenticated;
revoke execute on function private.lists_tick_business(uuid, timestamptz)
  from public, anon, authenticated, service_role;
revoke execute on function private.lists_tick(timestamptz, uuid)
  from public, anon, authenticated, service_role;
revoke execute on function private.notify_for_lists(public.audit_log)
  from public, anon, authenticated;
revoke execute on function private.seed_demo_lists(uuid)
  from public, anon, authenticated;
